using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;public void Execute(ExecutionResult result){for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved scene");Directory.CreateDirectory("Validation/FinalWorld");
foreach(var path in Directory.GetFiles("Assets/Scenes","*.unity",SearchOption.AllDirectories).Where(p=>!Path.GetFileName(p).StartsWith("_Recovery_")).OrderBy(p=>p)){var s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var lines=new List<string>();foreach(var r in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true))){var mf=r.GetComponent<MeshFilter>();var mesh=mf?mf.sharedMesh:r is SkinnedMeshRenderer sk?sk.sharedMesh:null;string info=P(r.transform)+"|"+(mesh?mesh.name:"")+"|"+AssetDatabase.GetAssetPath(mesh)+"|"+string.Join(";",r.sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m)));if(info.ToLower().Contains("tree")||info.ToLower().Contains("pine")||info.ToLower().Contains("shrub")||info.ToLower().Contains("bush")||info.ToLower().Contains("vegetation"))lines.Add((r.enabled&&r.gameObject.activeInHierarchy?"VISIBLE|":"HIDDEN|")+info+"|"+r.bounds.size);}
File.WriteAllLines("Validation/FinalWorld/"+s.name+"_vegetation.txt",lines);}
result.Log("Inventory complete");}}
